-- Bovine B3.13 accessions
select accession
from samples s
inner join samples_lineages sl on sl.sample_id = s.id
inner join lineages l on l.id = sl.lineage_id
where collection_start_date = collection_end_date
  and not is_retracted
  and host in ('cattle', 'cattle domestic dairy no breed specified', 'cattle milk product')
  and lineage_name = 'B3.13'
;

