-- Get phenotype annotation counts by month for all effects at once:

-- for all bovine samples, HA
WITH base as (
    select aa.id as aa_id,
           e.detail,
           (collection_start_date + ((collection_end_date - collection_start_date) / 2))::date AS mid_collection_date
    from samples s
    left join geo_locations gl on gl.id = s.geo_location_id
    inner join intra_host_variants VM on VM.sample_id = s.id
    inner join samples_lineages sl on sl.sample_id = s.id
    inner join lineages l ON l.id = sl.lineage_id
    inner join lineage_systems ls on ls.id = l.lineage_system_id
    left join intra_host_translations t on t.intra_host_variant_id = VM.id
    left join amino_acids aa on aa.id = t.amino_acid_id
    inner join annotations_amino_acids aaa on aaa.amino_acid_id = aa.id
    inner join annotations a on a.id = aaa.annotation_id
    inner join effects e on e.id = a.effect_id
    inner join annotations_papers ap on ap.annotation_id = a.id
    where num_nulls(collection_end_date, collection_start_date) = 0
      and collection_end_date - collection_start_date <= 366
      and host in ('cattle', 'cattle domestic dairy no breed specified', 'cattle milk product')
      and aa.gff_feature = 'XAJ25415.1'
),
     by_effect as (
    select detail,
           extract(year from mid_collection_date) as year,
           extract(month from mid_collection_date) as chunk,
           count(DISTINCT aa_id) as n
    from base
    group by year, chunk, detail
    order by year, chunk
),
     totals as (
    select extract(year from mid_collection_date) as year,
           extract(month from mid_collection_date) as chunk,
           count(distinct aa_id) as n_total
    from base
    group by year, chunk
)
select by_effect.*,
       totals.n_total
from by_effect
left join totals on totals.year = by_effect.year and totals.chunk = by_effect.chunk
;

-- for all avian samples, HA
