-- For these queries, the list of accessions comes from sras_qc_passed.txt, in the appropriate output dir.
-- get mutation and dms data for HA samples, bovine
select accession,
       ref_codon,
       alt_codon,
       ref_aa,
       position_aa,
       alt_aa,
       pm.phenotype_metric_name,
       pmv.value,
       collection_start_date as date
from samples s
inner join mutations m on m.sample_id = s.id
inner join mutation_translations t on t.mutation_id = m.id
inner join amino_acids aa on aa.id = t.amino_acid_id
inner join public.phenotype_metric_values pmv on pmv.amino_acid_id = aa.id
inner join public.phenotype_metrics pm on pm.id = pmv.phenotype_metric_id
where aa.gff_feature = 'XAJ25415.1'
  and s.accession in
      ('SRR35150518', 'SRR31821169', 'SRR30932743', 'SRR28912809', 'SRR35316980', 'SRR29543361', 'SRR31597014',
