-- get mutation and dms data for avian PB2
select accession,
       ref_codon,
       alt_codon,
       ref_aa,
       position_aa,
       alt_aa,
       pm.phenotype_metric_name,
       pmv.value,
       collection_start_date as date
from samples s
inner join mutations m on m.sample_id = s.id
inner join mutation_translations t on t.mutation_id = m.id
inner join amino_acids aa on aa.id = t.amino_acid_id
inner join public.phenotype_metric_values pmv on pmv.amino_acid_id = aa.id
inner join public.phenotype_metrics pm on pm.id = pmv.phenotype_metric_id
where aa.gff_feature = 'XAJ25426.1'
  and s.accession in
